-- Render field facts, never runtime acceptance, from the pinned source ledger.
package.path = 'scripts/?.lua;' .. package.path
local json = require('tool_json')
local input = assert(io.open('api/coverage.json', 'rb'))
local ledger = json.decode(input:read('*a')); input:close()
local function cell(v)
  if v == json.null or v == nil then return '—' end
  return tostring(v):gsub('|', '&#124;'):gsub('\n', ' ')
end
local out = {'# Native field manifest\n\n',
  'Generated by `lua5.4 scripts/render-fields.lua` from `api/coverage.json`.\n',
  'Source facts only, **not runtime acceptance or Lua call grammar**. All native\n',
  'model fields are retained (including full-tier/excluded models); the core\n',
  'grammar and envelope-to-model mapping are in [API](../docs/API.md) and\n',
  '[M3 core](../docs/M3-CORE.md#grammar-and-field-manifest) and\n',
  '[M4 full](../docs/M4-FULL.md#call-grammar-and-dispatch-manifest). See\n',
  '[SPEC](../docs/SPEC.md) for validation and effective downstream bounds.\n',
  'Native defaults do not imply optional positional Lua arguments. Nested model\n',
  'fields refer to the corresponding model below. UInt64 never uses floats.\n\n'}
local names = {}; for name in pairs(ledger.types) do names[#names+1] = name end
table.sort(names)
for _, name in ipairs(names) do
  out[#out+1] = '## ' .. name .. '\n\n| Field | Native type | Lua | Optional | Native default |\n| --- | --- | --- | --- | --- |\n'
  for _, f in ipairs(ledger.types[name].fields) do
    out[#out+1] = '| ' .. cell(f.name) .. ' | ' .. cell(f.native_type) .. ' | ' .. cell(f.lua) .. ' | ' .. cell(f.optional) .. ' | ' .. cell(f.native_default) .. ' |\n'
  end
  out[#out+1] = '\n'
end
local text = table.concat(out)
if arg[1] == '--check' then
  local f = assert(io.open('api/FIELDS.md', 'rb'))
  assert(f:read('*a') == text, 'api/FIELDS.md is stale'); f:close()
else
  assert(arg[1] == nil, 'usage: lua5.4 scripts/render-fields.lua [--check]')
  local f = assert(io.open('api/FIELDS.md', 'wb')); assert(f:write(text)); f:close()
end
